import streamlit as st
import pandas as pd
import plotly.express as px
import numpy as np

st.set_page_config(
    layout="wide",
    page_icon="⚡",
    page_title="Electricity Generation & Supply in the UK (1920-2024)"
)

# title
st.title("Electricity Generation & Supply in the UK (1920-2024)", text_alignment="center")

# read the excel file and get the sheet names
sheets = pd.read_excel("datasets\electricity_generation&supply_1920to2024_uk\Electricity_since_1920.xlsx", sheet_name=None)
df_electricity_DandS = sheets.get("Generated and Supplied").copy()

# Extract the sheet for the Estimated Historical Generation by soucre
est_hist_gen = sheets.get("Estimated Historical Generation").copy()
# clean the dataset
colms = list(est_hist_gen.iloc[3])
est_hist_gen.columns = colms
est_hist_gen.columns = est_hist_gen.columns.str.lower().str.replace(" ", "_", regex=False)

df_est_hist_gen = est_hist_gen.iloc[4:]

# convert the year column in df_est_hist_gen to a datetime format.
df_est_hist_gen['year'] = pd.to_datetime(df_est_hist_gen['year'], errors='coerce', format='%Y').dt.year

# convert numeric columns to int data type
df_est_hist_gen['coal_estimated_generation'] = df_est_hist_gen['coal_estimated_generation'].astype(int)

df_est_hist_gen.info()



# ------------------------------------------

# Build a filter options for filtering the year

all_years = df_est_hist_gen.year.tolist()

if "selected_years" not in st.session_state:
    st.session_state.selected_years = all_years
st.header('Filters')
with st.expander("Date filter"):
    selected_options = st.multiselect("Select the year", options=all_years, default=all_years)

# date filter button

if st.button("Filter"):
    if selected_options:
        st.session_state.selected_years = selected_options
    else:
        st.warning('No year has been selected !')

# filter out the year in the dataframe
filt_df_est_hit = df_est_hist_gen[df_est_hist_gen['year'].isin(st.session_state.selected_years)]

# create out data metrics

# Title
st.title("Electricity generation by source", text_alignment="center",)

# row 1
r1col1, r1col2, r1col3, r1col4, r1col5 = st.columns(5)
r2col1, r2col2, r2col3, r2col4 = st.columns(4)

# create a function to format numbers
def format_number(n):
    if n >= 1_000_000_000:
        return f"{n/1_000_000_000:.1f}B"
    elif n >= 1_000_000:
        return f"{n/1_000_000:.1f}M"
    elif n >= 1_000:
        return f"{n/1_000:.1f}K"
    return f"{n:.1f}"

with r1col1:
    with st.container(border=True):
        st.metric("Total", format_number(filt_df_est_hit.total_estimated_generation.sum()))
with r1col2:
    with st.container(border=True):
        st.metric("Coal", format_number(filt_df_est_hit.coal_estimated_generation.sum()))
with r1col3:
    with st.container(border=True):
        st.metric("Oil", format_number(filt_df_est_hit['oil_estimated_generation_[note_2]'].sum()))
with r1col4:
    with st.container(border=True, horizontal_alignment="center"):
        st.metric("Natural Gas", format_number(filt_df_est_hit['natural_gas_estimated_generation_[note_3]'].sum()))

with r1col5:
    with st.container(border=True, horizontal_alignment="center"):
        st.metric("Nuclear", format_number(filt_df_est_hit['nuclear_estimated_generation'].sum()))
with r2col1:
    with st.container(border=True, horizontal_alignment="center"):
        st.metric("Renewables", format_number(filt_df_est_hit['wind,_wave,_solar_and_hydro_estimated_generation_[note_4]'].sum()))
with r2col2:
    with st.container(border=True, horizontal_alignment="center"):
        st.metric("Coke&Breeze", format_number(filt_df_est_hit['coke_and_breeze_estimated_generation'].sum()))
with r2col3:
    with st.container(border=True, horizontal_alignment="center"):
        st.metric("Pumped storage", format_number(filt_df_est_hit['pumped_storage_share_of_generation'].sum()))
with r2col4:
    with st.container(border=True, horizontal_alignment="center"):
        st.metric("Others", format_number(filt_df_est_hit['other_fuels_estimated_generation_[note_5]'].sum()))


st.title("Source of electricity generation by share", text_alignment="center")

# Share of columns

share_cols = [  "coal_share_of_generation", 
                "oil_share_of_generation", 
                "natural_gas_share_of_generation",
                "nuclear_share_of_generation",
                "wind,_wave,_solar_and_hydro_share_of_generation",
                "coke_and_breeze_share_of_generation",
                "other_fuels_share_of_generation",
                "pumped_storage_share_of_generation"
                ],

share_labels = [
            "Coal",
            "Oil",
            "Natural Gas",
            "Nuclear",
            "Renewables",
            "Coke & Breeze",
            "Other Fuels",
            "Pumped Storage"
]

# summation of values from filtered dataframe
# Check what share_cols actually contains


# Make sure share_cols is a plain python list
share_cols = list(filt_df_est_hit.filter(like='share_of_generation').columns)

# Convert to numeric first
for col in share_cols:
    filt_df_est_hit[col] = pd.to_numeric(filt_df_est_hit[col], errors='coerce')

# Use .loc to select columns and sum
summed_values = [filt_df_est_hit.loc[:, col].sum() for col in share_cols]



# Build pie chart
pie_fig = px.pie(
    values=summed_values,
    names=share_labels,
    color_discrete_sequence=px.colors.qualitative.Pastel
)

pie_fig.update_layout(width=700, height=700)
pie_fig.update_traces(textfont={"size":30})
with st.container(border=True):
    st.plotly_chart(pie_fig)

