#st.plotly_chart(pie_fig)






# ------------------------------------------







row_arr = list(df_electricity_DandS.iloc[5])
#cleaned_arr = np.char.replace(row_arr, " ", "_")


df_electricity_DandS.drop(range(6), inplace=True)
df_electricity_DandS.reset_index(inplace=True)
df_electricity_DandS.drop("index", axis=1, inplace=True)

# Assign the new columns and clean the column titles
df_electricity_DandS.columns = row_arr
df_electricity_DandS.columns = df_electricity_DandS.columns.str.lower().str.replace(" ", "_", regex=False)

# change year dtype from object to datetime format
df_electricity_DandS['year'] = pd.to_datetime(df_electricity_DandS.year, errors='coerce', format='%Y')


# rename columns so as to make the legend readabke
df_electricity_DandS = df_electricity_DandS.rename(columns={
    "electricity_generated_(major_power_producers)": "Electricity Generated",
    "total_electricity_supplied_(gross,_major_power_producers)_[note_2]": "Net Electricity Supplied"
})


# Add a calculate column for the difference between electricity demand and supply.
df_electricity_DandS['Difference'] = df_electricity_DandS['Electricity Generated'] - df_electricity_DandS['Net Electricity Supplied']


# Plot a line chart to analyse the total electricity generated and supplied from 1920 to 2024

fig1 = px.line(
    df_electricity_DandS,
    x = 'year',
    y = ['Electricity Generated', 
         'Net Electricity Supplied',
         'Difference'
         ],
         
    color_discrete_sequence = px.colors.qualitative.Pastel,
    labels={
        "variable": "Legend"
    }, 
)

fig1.update_layout(
    xaxis_title="Amount(Twh)",
    yaxis_title="year",
    legend=dict(
        orientation="h",       # horizontal layout
        yanchor="bottom",
        y=1.02,                # pushes it just above the chart
        xanchor="center",
        x=0.5                  # centers it horizontally
    ),
)

fig1.update_xaxes(
    rangeslider_visible=False
)

with st.container(border=True):
    st.subheader("Electricity generation and supplied from 1920-2020", text_alignment="center")
    st.plotly_chart(fig1, width='stretch', key="fig1", height=650)




